// 번체 → 간체 (질문과 이름 맞추기에 쓰는 글자만)
const T2S = "門门費费錢钱時时間间點点開开關关館馆兒儿寶宝車车樓楼階阶輪轮嬰婴雙双邊边灘滩歷历術术園园齊齐鏡镜島岛灣湾韓韩國国東东亞亚來来這这個个們们麼么後后裡里裏里從从爾尔過过還还氣气濟济場场長长體体廳厅飯饭麵面餐餐魚鱼雞鸡燒烧樂乐歡欢買买賣卖價价寫写帶带陽阳禮礼紀纪產产藝艺綠绿華华臺台橋桥纜缆觀观廣广岡冈嶽岳嶺岭縣县龍龙鳳凤寺寺塔塔亭亭樹树歲岁傳传說说話话讀读書书畫画電电線线際际準准離离遠远近近幾几钟钟鐘钟條条燈灯島岛壩坝湧涌潮潮";
const T2S_MAP = new Map(); for (let i = 0; i + 1 < T2S.length; i += 2) T2S_MAP.set(T2S[i], T2S[i + 1]);
export const toSimplified = (t) => [...t].map((c) => T2S_MAP.get(c) || c).join("");

